/** Runtime invariant check for OverspeedMonitor. Returns empty array when valid. */
export function validateOverspeedMonitor(instance: OverspeedMonitor): readonly string[] {
  const violations: string[] = [];
  if (!((instance.monitorId !== null))) {
    violations.push("[OverspeedMonitor] invariant violated: self.monitorId <> null");
  }
  if (!((instance.maxSafeSpeed > 0))) {
    violations.push("[OverspeedMonitor] invariant violated: self.maxSafeSpeed > 0.0");
  }
  if (!((instance.currentSpeed >= 0))) {
    violations.push("[OverspeedMonitor] invariant violated: self.currentSpeed >= 0.0");
  }
  if (!((!(instance.overspeedActive) || (instance.currentSpeed > instance.maxSafeSpeed)))) {
    violations.push("[OverspeedMonitor] invariant violated: self.overspeedActive implies (self.currentSpeed > self.maxSafeSpeed)");
  }
  return violations;
}

